// Keep number formatting identical for every visitor, whatever their browser locale.
var _tl=Number.prototype.toLocaleString;
Number.prototype.toLocaleString=function(l,o){return _tl.call(this,l===undefined?'en-US':l,o);};
var NUM=/(?<![A-Za-z])\d+(?:[.,]\d+)*/g;
function locNum(t){
  if(/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(t))return t.replace(/[.,]/g,function(c){return c===','?'.':','});
  if(t.indexOf('.')>-1&&t.indexOf(',')<0)return t.replace('.',',');
  return t;
}
function locAll(s){return s.replace(NUM,locNum);}
var cache={};
function tr1(c){ // c: collapsed, trimmed string
  if(D.hasOwnProperty(c))return D[c];
  var nums=[],n=c.replace(NUM,function(m){nums.push(m);return '#';});
  if(nums.length&&T.hasOwnProperty(n)){var i=0;return T[n].replace(/#/g,function(){var v=nums[i++];return v===undefined?'#':locNum(v);});}
  return null;
}
